var status = msg.payload;
var state = context.get("currentState");
var msgAlt = { ...msg };
var mqttPath = msg.mqttDest;

if (mqttPath === undefined) {
    return [null, null]
}

var arr = mqttPath.split('/');
var mqttDest = arr[0] + "/" + arr[1] + "/" + arr[2] + "/" + arr[3] + "/" + arr[4] + "/" + "status";
msgAlt.topic = mqttDest;

// if green light is on, an temp increases
if (status == 5 && state == false) {
    //set light to red, and set status state to true
    context.set("currentState", true);
    msg.payload = 1;
    msgAlt.payload = 0;
    let gemnotif = LightState(msg, msgAlt);
    return [msg, gemnotif, msgAlt];
}

// if red light is one, and status goes down
if ((status >= 1 && status <= 3) && state == true) {
    // set light to green, and set state to false
    context.set("currentState", false);
    msg.payload = 0;
    msgAlt.payload = 1;
    let gemnotif = LightState(msg, msgAlt);
    return [msg, gemnotif, msgAlt];
}

if (status == 0 || status == 6) {
    msg.payload = 0;
    msgAlt.payload = 0;
    let gemnotif = LightState(msg, msgAlt);
    return [msg, gemnotif, msgAlt];
}

// if state is undefined
if (state == false || state == 'undefined') {
    // turn on green light
    msg.payload = 0;
    msgAlt.payload = 1;
    let gemnotif = LightState(msg, msgAlt);
    return [msg, gemnotif, msgAlt];
}

// finally is all else fails
else {
    //set light to red
    msg.payload = 1;
    msgAlt.payload = 0;
    let gemnotif = LightState(msg, msgAlt);
    return [msg, gemnotif, msgAlt];
}




function LightState(redlight, greenlight) {
    var r = redlight.payload;
    var g = greenlight.payload;
    if (r == 1 && g == 0){
        let ls = {};
        ls.topic = mqttDest;
        ls.payload = "red";
        return ls;
    }
    if (r == 0 && g == 1) {
        let ls = {};
        ls.topic = mqttDest;
        ls.payload = "green";
        return ls;
    }
    if (r == 0 && g == 0) {
        let ls = {};
        ls.topic = mqttDest;
        ls.payload = "off";
        return ls;
    }
}

