// This function sets the mqttDest property of 
// incoming message to the following format:
//
//      user/02/GEM/raspi_01/unit_01/data
// 
// It uses the global variable rasPiIndex, which
// specifies which of the three RasPi's this one is
// and is defined + set in the "local" flow.

let collectorIndex = global.get("rasPiIndex");
let inputTopic = msg.topic;

var arr = inputTopic.split('/')

msg.mqttDest = collectorIndex + arr[1] + "/data";

return msg;

// This function sets the mqttDest property of 
// incoming message to the following format:
//
//      esp32/unit_01/buzzerStatus
// 
// This poperty is used later in the processing for
// humidity limit calculations, and is dynamically
// adjusted based on the incoming message topic

let inputTopic = msg.topic;
var arr = inputTopic.split('/')
msg.mqttDest = arr[0] + "/" + arr[1] + "/buzzerStatus";

return msg;

let collectorIndex = global.get("rasPiIndex");
let inputTopic = msg.topic;

var arr = inputTopic.split('/')

msg.mqttDest = collectorIndex + arr[1] + "/data";

return msg;

let collectorIndex = global.get("rasPiIndex");
let inputTopic = msg.topic;

var arr = inputTopic.split('/')

msg.mqttDest = arr[0] + "/" + arr[1] + "/buzzerStatus";

return msg;

var nominal = msg.payload.nomUnit01; 
var temp = msg.payload.tempReading;
var dest = msg.mqttDest
var eBrake = msg.payload.e_stopSignal;

msg.payload.mqttDest = dest;
msg.topic = "tempData";
/*
status codes:
1 - solid green
2 - blinking yellow
3 - solid yellow
4 - blinking red
5 - solid red
6 - solid blue

0 - off;
*/

var upper10 = nominal * 1.1;
var upper20 = nominal * 1.2;
var upper30 = nominal * 1.3;
var upper50 = nominal * 1.5;
var lower10 = nominal * 0.9;
var lower20 = nominal * 0.8;
var lower30 = nominal * 0.7;
var lower50 = nominal * 0.5;

if (Number.isNaN(lower50)){return null}

msg.payload.ui_update = {
    min: lower50,
    max: upper50,
    segments: [ 
    { from: lower50, color: 'rgb(234, 83, 83)' },
    { from: lower30, color: 'rgb(200, 155, 0)' },
    { from: lower20, color: 'rgb(255, 200, 0)' },
    { from: lower10, color: 'rgb(92, 214, 92)' },
    { from: upper10, color: 'rgb(255, 200, 0)' },
    { from: upper20, color: 'rgb(200, 155, 0)' },
    { from: upper30, color: 'rgb(234, 83, 83)' }
    ]
}

if (eBrake == true) {
    msg.payload.status = 6;
    return msg;
}

if (nominal == null || temp == "nan"){
    msg.payload.status = 0;
    return msg;
}

if (temp >= upper10 && temp < upper20) {
    msg.payload.status = 2;
    return msg;
}
if (temp >= upper20 && temp < upper30) {
    msg.payload.status = 3;
    return msg;
}
if (temp >= upper30 && temp < upper50) {
    msg.payload.status = 4;
    return msg;
}
if (temp >= nominal * 1.5) {
    msg.payload.status = 5;
    return msg;
}

if (temp <= lower10 && temp > lower20) {
    msg.payload.status = 2;
    return msg;
}
if (temp <= lower20 && temp > lower30) {
    msg.payload.status = 3;
    return msg;
}
if (temp <= lower30 && temp > lower50) {
    msg.payload.status = 4;
    return msg;
}
if (temp <= lower50) {
    msg.payload.status = 5;
    return msg;
}

msg.payload.status = 1;
return msg;

try {
    var upper = msg.payload.nom.upperHum;
    var lower = msg.payload.nom.lowerHum;
    var reading = msg.payload.humReading;

    if (upper == null || lower == null) return null;
    if (reading == "nan" || reading == null) return null;

    msg.topic = msg.mqttDest;

    if (reading >= lower && reading <= upper) {
        msg.payload = 0;
    }
    else{
        msg.payload = 1;
    }

    return msg;
}
catch {
    return null;
}

